text:
.openpgp-more-btn > menupopup {
  appearance: none;
  font-size: 1em;
  --panel-border-color: var(--border-color);
  --panel-border-radius: 2px;
  --panel-background-color: var(--background-color-box);
  --panel-text-color: var(--color-text-base);
  --panel-padding: 3px 0;

  & > menuitem {
    appearance: none;
    color: var(--color-text-base);
    padding-block: 0.2em;
    padding-inline: 10px 30px;

    &[_moz-menuactive="true"] {
      color: inherit;
      background-color: var(--panel-background-color-dimmed);
    }

    &[selected] {
      color: var(--selected-item-text-color);
      background-color: var(--selected-item-color);
    }
  }
